{"results": [{"id": "hp_doc_4145eef0755af1c9d0aa1e97334545b5b048cf9aff1e2718c8fc901d552abd8b", "title": "Birth Control International Information Centre", "text": "The Birth Control International Information Centre (BCIIC) (1929–38) was a London-based independent, international clearinghouse for birth control information established by American birth control leader Margaret Sanger and British suffragist Edith How-Martyn. It supported the establishment of clinics and maternity advice centers abroad, sponsored lecture tours and a conference.", "score": 30.6047}, {"id": "hp_doc_3eb75b95924b6a94239775f987cacba0bdfbb576f211e87dff2c9267c0c98b0f", "title": "Frida Laski", "text": "Frida Kerry Laski (6 August 1884 – 31 July 1977) was a British suffragist, birth control advocate, and eugenicist.", "score": 29.5875}, {"id": "hp_doc_c32e6d39a21ea883a63622aa796554f25de3e953cd1e9d82adf00a8269a530f7", "title": "Katharine Russell, Viscountess Amberley", "text": "Katharine Louisa Russell, Viscountess Amberley (née Stanley; 3 April 1842 – 28 June 1874), often referred to as Kate, was a British suffragist and an early advocate of birth control in the United Kingdom. She was the mother of the philosopher Bertrand Russell.", "score": 24.6519}], "remaining_searches": 2}
